import shutil

QUERIES = [
    "status = 'paid'",
    "total_amount >= 250",
    "status = 'paid' AND total_amount >= 250",
    "invoice_date >= '2026-01-01'",
]


def write_table(invoices, path):
    # Partition by status, one file per status.
    invoices.write.format("delta").partitionBy("status").save(path)


def files_opened(path):
    # One row per query: the data files a read with that condition opens.
    return spark.createDataFrame([(query, 0) for query in QUERIES], "query STRING, files INT")


def solve(invoices):
    path = "/tmp/billing/by_status"
    shutil.rmtree(path, ignore_errors=True)  # start from an empty folder on every run
    feed = invoices.repartition(3)  # the feed hands the invoices over in three parts
    write_table(feed, path)
    return files_opened(path)
